import{_ as e,o as s,c as o,a6 as a}from"./chunks/framework.DIp0zHSV.js";const g=JSON.parse('{"title":"Getting Help","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/getting-help.md","filePath":"getting-started/getting-help.md","lastUpdated":1792162559000}'),i={name:"getting-started/getting-help.md"};function n(r,t,d,l,h,c){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h1><p>Something not working? Work through these in order: most problems are a config typo or a setup issue, and both are quick to rule out.</p><h2 id="_1-check-your-config" tabindex="-1">1. Check your config <a class="header-anchor" href="#_1-check-your-config" aria-label="Permalink to &quot;1. Check your config&quot;">​</a></h2><p>Paste your card YAML (or the whole dashboard) into <strong><a href="./config-checker.html">Check Your Config</a></strong>. It finds options that don&#39;t exist, misspelt preset, animation and colour names, and values of the wrong kind, each with the line and a suggestion. Fix what it reports first: a config LCARdS doesn&#39;t understand is silently ignored, which often looks like a bug.</p><p>Using Claude with the <a href="./ai-assistance.html#with-claude-easiest">LCARdS skill</a>? Paste the YAML and ask it to check and fix it.</p><h2 id="_2-run-the-health-check" tabindex="-1">2. Run the health check <a class="header-anchor" href="#_2-run-the-health-check" aria-label="Permalink to &quot;2. Run the health check&quot;">​</a></h2><p>Open the <strong>LCARdS</strong> sidebar panel → <strong>Welcome</strong> tab → <strong>Support &amp; system info</strong>.</p><p>The checklist covers the most common causes of problems:</p><table tabindex="0"><thead><tr><th>Check</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Home Assistant version</strong></td><td>LCARdS requires Home Assistant <strong>2026.10</strong> or newer.</td></tr><tr><td><strong>Frontend = integration version</strong></td><td>If these differ, your browser is running a cached copy of an older LCARdS. Hard-refresh (Ctrl+Shift+R / Cmd+Shift+R), or clear the companion app&#39;s frontend cache. If you just updated, restart Home Assistant.</td></tr><tr><td><strong>UI eXtension (UIX) / card-mod</strong></td><td>HA-LCARS styles Home Assistant through <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">UIX</a>. <strong>card-mod</strong> no longer works with current Home Assistant and conflicts with UIX. Uninstall it in HACS and remove its <code>extra_module_url</code> line from <code>configuration.yaml</code>.</td></tr><tr><td><strong>card-mod in <code>extra_module_url</code></strong></td><td>A leftover <code>frontend: extra_module_url</code> entry still loads card-mod. Remove it and restart.</td></tr><tr><td><strong>custom:layout-card</strong></td><td>Shown when <code>custom:layout-card</code> is installed. LCARdS cards can shrink inside it; switch to the LCARdS <a href="./../cards/layout-card/">Layout Card</a>.</td></tr><tr><td><strong>Lovelace resources</strong></td><td>LCARdS loads itself through the integration. An old manually added resource (e.g. <code>/hacsfiles/lcards/lcards.js</code>) or a duplicate loads it twice. Remove extras under <strong>Settings → Dashboards → ⋮ → Resources</strong>.</td></tr><tr><td><strong>HA-LCARS theme</strong></td><td>Shows whether an HA-LCARS theme is active. LCARdS works without it, but it is designed to pair with it.</td></tr></tbody></table><p>Resource and <code>extra_module_url</code> checks need an <strong>admin</strong> user.</p><h2 id="_3-common-problems" tabindex="-1">3. Common problems <a class="header-anchor" href="#_3-common-problems" aria-label="Permalink to &quot;3. Common problems&quot;">​</a></h2><ul><li><strong>Cards collapse or margins look wrong inside <code>custom:layout-card</code>:</strong> use LCARdS&#39;s own <a href="./../cards/layout-card/">Layout Card</a> instead. Change the <code>type</code> to <code>custom:lcards-layout-card</code> and remove <code>layout_type</code>; the rest of the config stays the same. See <a href="./../cards/common.html#sizing-inside-custom-layout-card">Sizing inside <code>custom:layout-card</code></a>.</li><li><strong>Cards look out of date after an update:</strong> hard-refresh the page (Ctrl+Shift+R / Cmd+Shift+R) or clear the companion app&#39;s frontend cache.</li><li><strong>Styling from card-mod stops working:</strong> card-mod no longer works with current Home Assistant; HA-LCARS uses <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">UIX</a> instead. Remove card-mod.</li><li><strong>Moving over from CB-LCARS?</strong> See <a href="./cb-lcars-migration.html">Coming from CB-LCARS</a> for the equivalent of each card.</li></ul><h2 id="_4-report-an-issue" tabindex="-1">4. Report an issue <a class="header-anchor" href="#_4-report-an-issue" aria-label="Permalink to &quot;4. Report an issue&quot;">​</a></h2><p>Still stuck? In the same section:</p><ul><li><strong>Report an issue</strong> opens a GitHub bug report with your LCARdS version, Home Assistant version and support info already filled in. It also copies the full info to your clipboard. Review the form, describe the problem, add your card YAML, then submit. Nothing is sent automatically.</li><li><strong>Copy support info</strong> copies the same information, to paste into an existing issue or a <a href="https://github.com/snootched/LCARdS/discussions" target="_blank" rel="noreferrer">Discussion</a>.</li><li>Tick <strong>Include data-source names &amp; entity IDs</strong> only if the problem involves data sources.</li></ul><p>Expand <strong>Preview what will be shared</strong> to see exactly what is included. That means versions, browser, theme, UIX/card-mod status, integration options and the most recent LCARdS warnings. Those warnings can mention entity names, so review before sharing.</p><div class="tip custom-block"><p class="custom-block-title">Please use the template</p><p>Issues need the bug report template so we have the versions and environment we need. Issues opened without it are labelled <code>needs-template</code>. Edit the issue to add the template sections, or use <strong>Report an issue</strong>.</p></div><h2 id="other-ways-to-collect-info" tabindex="-1">Other ways to collect info <a class="header-anchor" href="#other-ways-to-collect-info" aria-label="Permalink to &quot;Other ways to collect info&quot;">​</a></h2><p><strong>Download diagnostics</strong>, Home Assistant&#39;s standard diagnostics file: <strong>Settings → Devices &amp; services → LCARdS → ⋮ → Download diagnostics</strong>. It contains the same backend facts plus Home Assistant&#39;s own system information.</p><p><strong>Browser console</strong> (F12 → Console):</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.lcards.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// quick summary</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.lcards.support.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// copy full support info to the clipboard</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.lcards.support.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openIssue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// copy + open a pre-filled bug report</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.lcards.support.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">collect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// raw support data (object)</span></span></code></pre></div><p>Pass <code>{ includeConfig: true }</code> to the <code>support.*</code> calls to include data-source names and entity IDs.</p>`,22)])])}const u=e(i,[["render",n]]);export{g as __pageData,u as default};
